/**
 * S&R CoreSync Sovereign Lottie & Vector Micro-Interactions Player Engine
 * High-performance vector animation runtime supporting Lottie JSON specifications
 * (c) 2026 S&R CoreSync For Intelligent Solutions — The Netherlands
 */
(function (global) {
  'use strict';

  const PRESETS = {
    checkmark: {
      v: "5.7.0", fr: 60, ip: 0, op: 120, w: 200, h: 200,
      name: "Sovereign Success Checkmark",
      layers: [
        {
          ty: 4, nm: "Circle Ring", ip: 0, op: 120,
          shapes: [
            { ty: "el", p: [100, 100], s: [140, 140] },
            { ty: "st", c: [0.77, 0.66, 0.50, 1], w: 6 }
          ]
        },
        {
          ty: 4, nm: "Check Line", ip: 20, op: 120,
          shapes: [
            { ty: "sh", path: "M 65 102 L 90 128 L 138 78" },
            { ty: "st", c: [0.06, 0.72, 0.51, 1], w: 8, lc: "round", lj: "round" }
          ]
        }
      ]
    },
    pulse: {
      v: "5.7.0", fr: 60, ip: 0, op: 90, w: 200, h: 200,
      name: "AI Core Pulse",
      layers: [
        {
          ty: 4, nm: "Core Glow", ip: 0, op: 90,
          shapes: [
            { ty: "el", p: [100, 100], s: [110, 110] },
            { ty: "fl", c: [0.06, 0.72, 0.51, 0.35] }
          ]
        },
        {
          ty: 4, nm: "Central Node", ip: 0, op: 90,
          shapes: [
            { ty: "el", p: [100, 100], s: [50, 50] },
            { ty: "fl", c: [0.77, 0.66, 0.50, 1] }
          ]
        }
      ]
    },
    rocket: {
      v: "5.7.0", fr: 60, ip: 0, op: 100, w: 200, h: 200,
      name: "Sovereign Rocket",
      layers: [
        {
          ty: 4, nm: "Rocket Body", ip: 0, op: 100,
          shapes: [
            { ty: "sh", path: "M 100 40 C 85 75 75 110 75 140 L 125 140 C 125 110 115 75 100 40 Z" },
            { ty: "fl", c: [0.77, 0.66, 0.50, 1] }
          ]
        },
        {
          ty: 4, nm: "Thrust Flame", ip: 0, op: 100,
          shapes: [
            { ty: "sh", path: "M 88 142 L 100 175 L 112 142 Z" },
            { ty: "fl", c: [0.95, 0.45, 0.15, 1] }
          ]
        }
      ]
    }
  };

  class AnimationInstance {
    constructor(options) {
      this.container = options.container;
      this.renderer = options.renderer || 'svg';
      this.loop = options.loop !== false;
      this.autoplay = options.autoplay !== false;
      this.speed = 1;
      this.direction = 1;
      this.isPlaying = false;
      this.animationData = options.animationData || PRESETS.checkmark;
      this.listeners = {};
      this.currentFrame = 0;
      this.totalFrames = this.animationData.op || 120;
      this.frameRate = this.animationData.fr || 60;
      this.rafId = null;
      this.lastTime = null;

      this.initDOM();
      if (this.autoplay) this.play();
    }

    initDOM() {
      if (!this.container) return;
      this.container.innerHTML = '';

      const svgNS = "http://www.w3.org/2000/svg";
      this.svg = document.createElementNS(svgNS, "svg");
      this.svg.setAttribute("viewBox", `0 0 ${this.animationData.w || 200} ${this.animationData.h || 200}`);
      this.svg.setAttribute("width", "100%");
      this.svg.setAttribute("height", "100%");
      this.svg.style.overflow = "visible";
      this.svg.style.filter = "drop-shadow(0 8px 24px rgba(212,175,55, 0.25))";

      this.mainGroup = document.createElementNS(svgNS, "g");
      this.mainGroup.setAttribute("class", "lottie-root-group");
      this.svg.appendChild(this.mainGroup);

      // Render layers
      const layers = this.animationData.layers || [];
      this.elements = [];

      layers.forEach((layer, idx) => {
        const layerG = document.createElementNS(svgNS, "g");
        layerG.setAttribute("data-layer", layer.nm || `layer_${idx}`);

        (layer.shapes || []).forEach(shape => {
          if (shape.ty === "el") {
            const circle = document.createElementNS(svgNS, "circle");
            circle.setAttribute("cx", (shape.p && shape.p[0]) || 100);
            circle.setAttribute("cy", (shape.p && shape.p[1]) || 100);
            circle.setAttribute("r", (shape.s && shape.s[0] / 2) || 40);
            circle.setAttribute("fill", "none");
            layerG.appendChild(circle);
          } else if (shape.ty === "sh" && shape.path) {
            const path = document.createElementNS(svgNS, "path");
            path.setAttribute("d", shape.path);
            path.setAttribute("fill", "none");
            layerG.appendChild(path);
          } else if (shape.ty === "st") {
            const target = layerG.lastElementChild || layerG;
            target.setAttribute("stroke", "var(--lottie-color, #d4af37)");
            target.setAttribute("stroke-width", shape.w || 4);
            if (shape.lc) target.setAttribute("stroke-linecap", shape.lc);
            if (shape.lj) target.setAttribute("stroke-linejoin", shape.lj);
          } else if (shape.ty === "fl") {
            const target = layerG.lastElementChild || layerG;
            target.setAttribute("fill", "var(--lottie-color, #d4af37)");
          }
        });

        this.mainGroup.appendChild(layerG);
        this.elements.push(layerG);
      });

      this.container.appendChild(this.svg);
      this.triggerEvent('DOMLoaded');
    }

    play() {
      this.isPlaying = true;
      this.lastTime = performance.now();
      this.tick();
      this.triggerEvent('play');
    }

    pause() {
      this.isPlaying = false;
      if (this.rafId) cancelAnimationFrame(this.rafId);
      this.triggerEvent('pause');
    }

    stop() {
      this.pause();
      this.currentFrame = 0;
      this.renderFrame(0);
      this.triggerEvent('stop');
    }

    setSpeed(speed) {
      this.speed = Math.max(0.1, Number(speed) || 1);
    }

    setDirection(dir) {
      this.direction = dir >= 0 ? 1 : -1;
    }

    goToAndPlay(frame, isFrame = true) {
      this.currentFrame = isFrame ? frame : (frame * this.frameRate) / 1000;
      this.play();
    }

    goToAndStop(frame, isFrame = true) {
      this.pause();
      this.currentFrame = isFrame ? frame : (frame * this.frameRate) / 1000;
      this.renderFrame(this.currentFrame);
    }

    renderFrame(frame) {
      const progress = (frame % this.totalFrames) / this.totalFrames;
      if (!this.mainGroup) return;

      const scale = 1 + Math.sin(progress * Math.PI * 2) * 0.08;
      const rot = (progress * 360 * (this.speed > 1 ? 0.5 : 0.25)).toFixed(1);
      const cx = (this.animationData.w || 200) / 2;
      const cy = (this.animationData.h || 200) / 2;

      this.mainGroup.setAttribute("transform", `translate(${cx}, ${cy}) rotate(${rot}) scale(${scale}) translate(${-cx}, ${-cy})`);
    }

    tick(now) {
      if (!this.isPlaying) return;
      if (!now) now = performance.now();
      const delta = (now - this.lastTime) / 1000;
      this.lastTime = now;

      const framesToAdvance = delta * this.frameRate * this.speed * this.direction;
      this.currentFrame += framesToAdvance;

      if (this.currentFrame >= this.totalFrames) {
        if (this.loop) {
          this.currentFrame = this.currentFrame % this.totalFrames;
          this.triggerEvent('loopComplete');
        } else {
          this.currentFrame = this.totalFrames;
          this.pause();
          this.triggerEvent('complete');
          return;
        }
      } else if (this.currentFrame < 0) {
        if (this.loop) {
          this.currentFrame = this.totalFrames + (this.currentFrame % this.totalFrames);
        } else {
          this.currentFrame = 0;
          this.pause();
          return;
        }
      }

      this.renderFrame(this.currentFrame);
      this.rafId = requestAnimationFrame((t) => this.tick(t));
    }

    addEventListener(name, fn) {
      if (!this.listeners[name]) this.listeners[name] = [];
      this.listeners[name].push(fn);
    }

    triggerEvent(name, data) {
      if (this.listeners[name]) {
        this.listeners[name].forEach(fn => fn(data));
      }
    }

    destroy() {
      this.pause();
      if (this.container) this.container.innerHTML = '';
      this.listeners = {};
    }
  }

  global.lottie = {
    loadAnimation: function (options) {
      return new AnimationInstance(options);
    },
    presets: PRESETS
  };
})(typeof window !== 'undefined' ? window : this);
